import 'dart:convert';import 'dart:io';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/component_catalogue/component_catalogue_model.dart';
void main(){
 test('21 TypeScript oracle cases match native code emphasis countdown and responsive form geometry',(){final f=jsonDecode(File('test/component_catalogue/model-fixtures.json').readAsStringSync()) as Map<String,dynamic>;for(final raw in f['code'] as List){final c=raw as Map;expect(codeTokens(c['input']).map((t)=>t.toJson()).toList(),c['tokens']);}for(final raw in f['countdown'] as List){final c=raw as Map;expect(remainingSeconds(c['deadline'],c['now']),c['remaining']);}for(final raw in f['columns'] as List){final c=raw as Map;expect(responsiveColumns((c['width'] as num).toDouble(),(c['minWidth'] as num).toDouble(),(c['gap'] as num).toDouble()),c['columns']);}});
 test('malformed geometry/time and oversized source remain errors',(){expect(()=>codeTokens('x'*32769),throwsFormatException);expect(()=>remainingSeconds(-1,0),throwsFormatException);expect(()=>remainingSeconds(1.5,0),throwsFormatException);expect(()=>responsiveColumns(double.nan,1,1),throwsFormatException);expect(()=>responsiveColumns(100,0,1),throwsFormatException);});
}
